#include <cmath>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common Polybench-style definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for cholesky (DATA_TYPE, N, etc.)
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize matrix A as in the original Polybench C code, but use
// Halide pipelines with an explicit schedule for better locality and
// parallelism during the (untimed) initialization phase.
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We follow the convention: A(j, i) == A[i][j] from the original C.
    Var i("i"), j("j");

    // ------------------------------------------------------------------
    // 1) Build the initial lower-triangular seed matrix in A.
    //
    // Original C:
    //   for (i = 0; i < n; i++) {
    //     for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //     for (j = i+1; j < n; j++)
    //       A[i][j] = 0;
    //     A[i][i] = 1;
    //   }
    //
    // Mapping to Halide: A(j, i) corresponds to A[i][j].
    // ------------------------------------------------------------------
    Func init_tri("init_tri");

    Expr j_mod_n = j % n;
    Expr val = cast<num_t>(-j_mod_n);
    val = val / cast<num_t>(n) + cast<num_t>(1);

    // Lower-triangular (including diagonal) gets 'val', above-diagonal is 0.
    init_tri(j, i) = select(j <= i, val, cast<num_t>(0));

    // Explicitly set the diagonal to 1 (overrides the previous definition).
    init_tri(i, i) = cast<num_t>(1);

    // Simple but effective schedule for initialization:
    //  - Parallelize over rows (i).
    //  - Vectorize across columns (j).
    Target host_target = get_host_target();
    const int vec_width = natural_vector_size(type_of<num_t>(), host_target);

    init_tri
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize directly into A.
    init_tri.realize(A);

    // ------------------------------------------------------------------
    // 2) Make the matrix symmetric positive semi-definite:
    //    B = A * A^T, then copy B back into A.
    //
    // Original C (conceptually):
    //   for (t = 0; t < n; ++t)
    //     for (r = 0; r < n; ++r)
    //       for (s = 0; s < n; ++s)
    //         B[r][s] += A[r][t] * A[s][t];
    //   A[r][s] = B[r][s];
    //
    // With mapping A(j, i) == A[i][j]:
    //   A[r][t] -> A(t, r)
    //   A[s][t] -> A(t, s)
    //   B[r][s] -> B(s, r) in Halide indexing.
    //
    // We express this as a Halide reduction and apply a GEMM-like schedule.
    // ------------------------------------------------------------------
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func B_func("B_func");
    // B_func(s, r) holds B[r][s]
    B_func(s, r) = cast<num_t>(0);
    B_func(s, r) += A_param(t, r) * A_param(t, s);

    // Schedule for B_func:
    //  - Tile over (s, r) to get cache-friendly tiles.
    //  - Parallelize over tile rows (yo).
    //  - Vectorize across the inner s-dimension in the pure and update steps.
    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");
    RVar to("to"), ti("ti");
    const int tile_s = 32;
    const int tile_r = 32;
    const int t_block = 64;

    // Pure definition (initialization of B)
    B_func
        .compute_root()
        .tile(s, r, xo, yo, xi, yi, tile_s, tile_r)
        .parallel(yo)
        .vectorize(xi, vec_width);

    // Update definition (reduction over t)
    B_func.update()
        .tile(s, r, xo, yo, xi, yi, tile_s, tile_r)
        .split(t, to, ti, t_block)
        .reorder(xi, yi, ti, to, xo, yo)
        .parallel(yo)
        .vectorize(xi, vec_width);

    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A. This is O(n^2) and negligible vs. O(n^3) above,
    // so a simple loop is sufficient here.
    for (int rr = 0; rr < n; ++rr) {
        for (int ss = 0; ss < n; ++ss) {
            A(ss, rr) = B(ss, rr);
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // We follow the convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code (but via Halide).
    init_array(n, A);

    // Time only the Cholesky factorization kernel, as in the original.
    auto start = std::chrono::high_resolution_clock::now();

    // ------------------------------------------------------------------
    // Cholesky factorization kernel (optimized C++ implementation).
    //
    // Original algorithm (in terms of A[i][j] row-major):
    //
    //   for (i = 0; i < n; i++) {
    //     // off-diagonal
    //     for (j = 0; j < i; j++) {
    //       for (k = 0; k < j; k++)
    //         A[i][j] -= A[i][k] * A[j][k];
    //       A[i][j] /= A[j][j];
    //     }
    //     // diagonal
    //     for (k = 0; k < i; k++)
    //       A[i][i] -= A[i][k] * A[i][k];
    //     A[i][i] = sqrt(A[i][i]);
    //   }
    //
    // With our mapping A(j, i) == A[i][j], this becomes:
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //   A[j][j]   -> A(j, j)
    //   A[i][i]   -> A(i, i)
    //
    // The algorithm is inherently sequential in i and j due to data
    // dependencies, so we do not parallelize these loops. We instead:
    //   - block in i to improve cache locality,
    //   - manually unroll the inner dot products over k to increase ILP.
    // ------------------------------------------------------------------

    constexpr int TILE_I = 32;  // panel height for outer i loop (tunable)

    for (int i_block = 0; i_block < n; i_block += TILE_I) {
        const int i_end = std::min(i_block + TILE_I, n);

        for (int i = i_block; i < i_end; ++i) {
            // Pointer to the start of row i in logical row-major layout:
            // row_i[j] == A(j, i) == A[i][j] in the original C code.
            num_t *row_i = &A(0, i);

            // Off-diagonal elements in row i: 0 <= j < i.
            for (int j = 0; j < i; ++j) {
                num_t *row_j = &A(0, j);

                // Compute the dot product sum_{k=0}^{j-1} A[i][k] * A[j][k]
                // as sum_{k=0}^{j-1} row_i[k] * row_j[k], with manual
                // unrolling by 4 for better ILP. The inner loop walks
                // along the contiguous x-dimension of the Halide buffer.
                num_t sum = static_cast<num_t>(0);
                int k = 0;

                // Unrolled main loop, 4 elements per iteration.
                for (; k + 3 < j; k += 4) {
                    sum += row_i[k] * row_j[k]
                         + row_i[k + 1] * row_j[k + 1]
                         + row_i[k + 2] * row_j[k + 2]
                         + row_i[k + 3] * row_j[k + 3];
                }
                // Remainder loop for 0–3 elements.
                for (; k < j; ++k) {
                    sum += row_i[k] * row_j[k];
                }

                // A[i][j] = (A[i][j] - sum) / A[j][j]
                row_i[j] = (row_i[j] - sum) / row_j[j];
            }

            // Diagonal element A[i][i].
            // Compute sum_{k=0}^{i-1} A[i][k]^2 with the same unrolling.
            num_t sum_diag = static_cast<num_t>(0);
            int k = 0;
            for (; k + 3 < i; k += 4) {
                sum_diag += row_i[k] * row_i[k]
                          + row_i[k + 1] * row_i[k + 1]
                          + row_i[k + 2] * row_i[k + 2]
                          + row_i[k + 3] * row_i[k + 3];
            }
            for (; k < i; ++k) {
                sum_diag += row_i[k] * row_i[k];
            }

            // A[i][i] = sqrt(A[i][i] - sum_diag)
            const num_t diag_val = row_i[i] - sum_diag;
            row_i[i] = static_cast<num_t>(
                std::sqrt(static_cast<double>(diag_val)));
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
