    // 2) Make the matrix positive semi-definite:
    //
    // C code:
    // int r, s, t;
    // B[r][s] = 0;
    // for (t = 0; t < n; ++t)
    //   for (r = 0; r < n; ++r)
    //     for (s = 0; s < n; ++s)
    //       B[r][s] += A[r][t] * A[s][t];
    // A[r][s] = B[r][s];
    //
    // This is B = A * A^T where A is n x n lower-triangular.
    //
    // We express this as a Halide reduction and schedule it like a
    // small GEMM, tiled and parallelized for cache locality and SIMD.
    // ------------------------------------------------------------------

