    Var so("so"), ro("ro"), si("si"), ri("ri");
    Var tile_index("tile_index");
    RVar t_outer("t_outer"), t_inner("t_inner");

    // Reasonable tile sizes for a modern x64 with large caches.
    const int tile_s = 32;
    const int tile_r = 32;
    const int tile_t = 64;

