        .compute_root()
        // Tile output space into tile_s x tile_r blocks.
        .tile(s, r, so, ro, si, ri, tile_s, tile_r)
        // Fuse the two tile indices so and ro into a single parallel dimension.
        .fuse(so, ro, tile_index)
        // Parallelize across tiles.
        .parallel(tile_index)
        // Vectorize along the contiguous x-dimension inside each tile.
        .vectorize(si, vec_width);

    // Schedule the reduction update:
    B_func.update()
        // Split the reduction over t into tiles of size tile_t.
        .split(t_dom, t_outer, t_inner, tile_t)
        // Reorder to make the innermost loop iterate over t_inner,
        // then over the fast x-dimension (si), then y (ri).
        .reorder(t_inner, si, ri, t_outer, tile_index)
        // Vectorize the innermost part of the reduction.
        .vectorize(t_inner, vec_width);

    // Realize B_func into a temporary buffer B.
    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A.
    // A(ss, rr) == A[rr][ss] in original C code; B has the same layout.
    for (int rr = 0; rr < n; ++rr) {
        for (int ss = 0; ss < n; ++ss) {
            A(ss, rr) = B(ss, rr);
        }
    }
