// pipelines with an optimized schedule for both the triangular seed matrix
// and the SPD construction A = L0 * L0^T.
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // A is laid out as A(j, i) == A[i][j] from the C code:
    //   - dimension 0 (x) == column index j
    //   - dimension 1 (y) == row index i
    Var i("i"), j("j");

    // ------------------------------------------------------------------
    // 1) Build initial lower-triangular seed matrix L0 into A.
    //
    // C reference:
    //   for (i = 0; i < n; i++) {
    //     for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //     for (j = i+1; j < n; j++)
    //       A[i][j] = 0;
    //     A[i][i] = 1;
    //   }
    //
    // Mapping: A[i][j] -> A(j, i).
    // ------------------------------------------------------------------
    Func init_tri("init_tri");

    Expr val = cast<num_t>(-(j % n));
    val = val / cast<num_t>(n) + cast<num_t>(1);

    // Lower-triangular (including diagonal) gets 'val', above-diagonal is 0.
    init_tri(j, i) = select(j <= i, val, cast<num_t>(0));

    // Explicitly set the diagonal to 1.
    init_tri(i, i) = cast<num_t>(1);

    // Choose a reasonable SIMD width for this machine and element type.
    Target init_target = get_jit_target_from_environment();
    const int vec_width = init_target.natural_vector_size(type_of<num_t>());

    // Simple but effective schedule:
    //  - compute_root so the whole matrix is realized once
    //  - parallelize across rows (i)
    //  - vectorize across columns (j)
    init_tri
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_tri.compile_jit(init_target);
    init_tri.realize(A);

    // ------------------------------------------------------------------
    // 2) Make the matrix symmetric positive semi-definite:
    //      B[r][s] = sum_t A[r][t] * A[s][t];
    //      A[r][s] = B[r][s];
    //
    // This is B = A * A^T where A is the lower-triangular L0.
    // We express B as a Halide reduction and then copy back into A.
    // ------------------------------------------------------------------
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    Var r("r"), s("s");
    RDom t(0, n, "t");  // reduction over the shared inner dimension

    Func B_func("B_func");
    B_func(s, r) = cast<num_t>(0);
    // A[r][t] -> A_param(t, r);  A[s][t] -> A_param(t, s)
    B_func(s, r) += A_param(t, r) * A_param(t, s);

    // Treat B_func as a GEMM-like kernel:
    //  - dimension 1 (r) is the row index -> parallelize over rows
    //  - dimension 0 (s) is contiguous -> vectorize over columns
    B_func
        .compute_root()
        .parallel(r)
        .vectorize(s, vec_width);

    // For the update (reduction) step, make 's' innermost so that
    // vectorization reads contiguous A[s, t].
    B_func.update()
        .reorder(s, t, r)
        .vectorize(s, vec_width)
        .parallel(r);

    B_func.compile_jit(init_target);

    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A (still in (j, i) == A[i][j] layout).
    for (int rr = 0; rr < n; ++rr) {
        for (int ss = 0; ss < n; ++ss) {
            A(ss, rr) = B(ss, rr);
        }
    }
}

