    int n = N;

    // Matrix A, using Halide::Buffer.
    // Convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code (seed lower-triangular
    // matrix, then SPD = L0 * L0^T).
    init_array(n, A);

    // ----------------------------------------------------------------------
    // Set up Halide pipelines for the Cholesky factorization kernel.
    //
    // We keep the outer loops over rows (i) and columns (j) in C++,
    // as the Cholesky algorithm has strong loop-carried dependencies:
    //
    //   for (i = 0; i < n; i++) {
    //     for (j = 0; j < i; j++) {
    //       for (k = 0; k < j; k++)
    //         A[i][j] -= A[i][k] * A[j][k];
    //       A[i][j] /= A[j][j];
    //     }
    //     for (k = 0; k < i; k++)
    //       A[i][i] -= A[i][k] * A[i][k];
    //     A[i][i] = sqrt(A[i][i]);
    //   }
    //
    // Instead of expressing the full recurrence as a single Func (which
    // would violate Halide's purity constraints), we express the inner
    // dot-products as Halide reductions parameterized by (i, j) through
    // scalar Params, and call these pipelines from the C++ loops.
    //
    // This lets Halide perform vectorized inner products while we keep
    // the required sequential order in i and j on the host side.
    // ----------------------------------------------------------------------

    // ImageParam to access the current contents of A from Halide.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);  // backed directly by the Buffer A

    // Scalar Params selecting the current row (i) and column (j).
    Param<int> i_param("i_param"), j_param("j_param");

    Var dummy("dummy");  // 1D dummy var for scalar Funcs

    // ------------------------------------------------------------------
    // Off-diagonal update:
    //
    //   A[i][j] = (A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[j][k]) / A[j][j]
    //
    // Using mapping A[i][j] -> A(j, i):
    //   A[i][j]   -> A_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //   A[j][j]   -> A_param(j, j)
    // ------------------------------------------------------------------
    RDom k_off(0, j_param, "k_off");

    Func offdiag("offdiag");
    {
        Expr dot_ij = sum(A_param(k_off, i_param) * A_param(k_off, j_param));
        Expr a_ij_orig = A_param(j_param, i_param);
        Expr a_jj = A_param(j_param, j_param);
        offdiag(dummy) = (a_ij_orig - dot_ij) / a_jj;
    }

    // ------------------------------------------------------------------
    // Diagonal update:
    //
    //   A[i][i] = sqrt( A[i][i] - sum_{k=0}^{i-1} A[i][k] * A[i][k] )
    //
    // Again using A[i][k] -> A(k, i).
    // We mirror the original numeric behavior by doing the sqrt in
    // double precision and casting back to num_t.
    // ------------------------------------------------------------------
    RDom k_diag(0, i_param, "k_diag");

    Func diag_func("diag_func");
    {
        Expr dot_ii = sum(A_param(k_diag, i_param) * A_param(k_diag, i_param));
        Expr a_ii_orig = A_param(i_param, i_param);
        Expr base = a_ii_orig - dot_ii;
        Expr diag_sqrt = cast<num_t>(sqrt(cast<double>(base)));
        diag_func(dummy) = diag_sqrt;
    }

    // ------------------------------------------------------------------
    // Schedule the inner-product pipelines.
    //
    // The reductions over k_off and k_diag are pure dot products over a
    // contiguous dimension (the first dimension of A, i.e., columns),
    // so we vectorize across k for good SIMD utilization.
    // ------------------------------------------------------------------
    Target chol_target = get_jit_target_from_environment();
    const int vec_k = chol_target.natural_vector_size(type_of<num_t>());

    // Vectorize the reduction dimension in both pipelines.
    offdiag.update().vectorize(k_off.x, vec_k);
    diag_func.update().vectorize(k_diag.x, vec_k);

    offdiag.compile_jit(chol_target);
    diag_func.compile_jit(chol_target);

    // ------------------------------------------------------------------
    // Time the Cholesky factorization kernel (as in the original code).
    // The initialization (init_array) runs outside the timed region.
    // ------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Temporary 1D buffers to hold scalar results from the Halide funcs.
    Halide::Buffer<num_t> tmp_off(1);
    Halide::Buffer<num_t> tmp_diag(1);

    for (int i = 0; i < n; i++) {
        // Off-diagonal elements in row i: j = 0 .. i-1
