static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // ---------------------------------------------------------------------
    // 1) Build the initial unit-diagonal lower-triangular matrix in A.
    //
    // C reference:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Mapping to Halide: A(j, i) == A[i][j].
    // ---------------------------------------------------------------------
    Var i("i"), j("j");

    Func init_tri("init_tri");

    Expr n_expr = cast<num_t>(n);
    Expr j_mod = j % n;  // j in [0, n), so this is just j, but mirrors the C code.
    Expr val = cast<num_t>(-j_mod);
    val = val / n_expr + cast<num_t>(1);

    // Lower-triangular (including diagonal) gets 'val', above-diagonal is 0.
    init_tri(j, i) = select(j <= i, val, cast<num_t>(0));

    // Explicitly set the diagonal to 1 (matches the Polybench code).
    init_tri(i, i) = cast<num_t>(1);

    // Schedule: compute at root, parallelize over rows (i), vectorize
    // across the contiguous dimension (j).
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) vec_width = 1;

    Var jo("jo"), ji("ji");
    init_tri
        .compute_root()
        // Split j into a vectorized inner loop ji and outer loop jo.
        .split(j, jo, ji, vec_width)
        .reorder(ji, jo, i)  // ji innermost -> contiguous in memory
        .vectorize(ji)
        .parallel(i);

    // Realize into the provided buffer A.
    init_tri.realize(A);

    // ---------------------------------------------------------------------
    // 2) Make the matrix symmetric positive semi-definite:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    // A[r][s] = B[r][s];
    //
    // This is B = A * A^T with A lower-triangular, but we still
    // implement the full dense multiply.
    // ---------------------------------------------------------------------

    // Wrap A in an ImageParam so we can treat it as input to the GEMM.
    ImageParam A_param(type_of<num_t>(), 2, "A_param_init");
    A_param.set(A);

    Var r("r"), s("s");
    RDom t_dom(0, n, "t");

    // B_func(s, r) represents B[r][s] in C indexing.
    Func B_func("B_func");
    B_func(s, r) = cast<num_t>(0);
    // A[r][t] -> A_param(t, r);  A[s][t] -> A_param(t, s).
    B_func(s, r) += A_param(t_dom, r) * A_param(t_dom, s);

    // Schedule for B_func:
    //   - compute_root so both the pure definition and the update are
    //     scheduled at top level,
    //   - parallelize over rows (r),
    //   - vectorize over contiguous columns (s),
    //   - reorder the reduction so that t_dom.x is innermost, enabling
    //     a clean vectorizable inner loop over s.
    B_func
        .compute_root()
        .parallel(r)
        .vectorize(s, vec_width);

    B_func.update()
        .reorder(t_dom.x, s, r)
        .parallel(r)
        .vectorize(s, vec_width);

    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A. This is O(n^2) and negligible versus the O(n^3)
    // SPD construction above.
    for (int rr = 0; rr < n; ++rr) {
        for (int ss = 0; ss < n; ++ss) {
            A(ss, rr) = B(ss, rr);
        }
    }
}

int main(int argc, char *argv[]) {
